function element(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;}
function age(seconds){return seconds<1?'now':seconds<60?Math.floor(seconds)+'s ago':seconds<3600?Math.floor(seconds/60)+'m ago':Math.floor(seconds/3600)+'h ago';}
function signalText(d){const value=d.last_rssi??d.rssi;if(value==null)return 'No measurement';const age=d.rssi_age??d.age;return value+' dBm'+(age>10?' · stale '+Math.floor(age)+'s':age>2?' · '+Math.floor(age)+'s ago':'');}
function privateView(){return privacyOverride??!!state.privacy;}
function address(d){return privateView()?'[hidden address]':d.address;}
function name(d){return privateView()?'Contact '+String(hash(d.key||d.address||'')%100000).padStart(5,'0'):(d.local_label||d.network_name||d.name||d.hits[0]?.label||(d.protocol==='wifi'?(d.wifi_role==='client'?(d.vendor?.status==='vendor_only'?d.vendor.name:'Wi-Fi client'):d.ssid_status==='hidden'?'Hidden SSID':'SSID not captured'):'Unnamed Bluetooth'));}
function radarName(d){return privateView()||d.local_label?name(d):d.protocol==='wifi'?(d.network_name||d.name||d.hits[0]?.label||'?'):name(d);}
function notice(message){$('notice').textContent=message;$('notice').hidden=false;}
async function api(path,data){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),8000);try{const options=data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-PagerWatch':'1'},body:JSON.stringify(data)};options.signal=controller.signal;const response=await fetch(path,options);const result=await response.json();if(!response.ok){if(response.status===401)showLogin();throw Error(result.error||'Request failed');}return result;}finally{clearTimeout(timeout);}}
async function resumeGPS(){if(!sharing||gpsResumeBusy||Date.now()-lastResume<10000||state.gps?.sharing)return;gpsResumeBusy=true;lastResume=Date.now();try{await api('/api/gps/start',{});$('gpsMessage').textContent='GPS sharing reconnected. Waiting for a new phone fix.';}catch(err){$('gpsMessage').textContent='GPS sharing needs attention: '+err.message;}finally{gpsResumeBusy=false;}}

