 $('gpsHeadingStatus').textContent=hasFix&&hidden?'Heading hidden by Privacy mode.':!hasFix?'Waiting for phone location.':!gps.valid?'Heading paused: '+health.toLowerCase()+'.':heading===null?'Heading unavailable. Your phone may need to be moving.':'Phone-reported direction of travel, relative to true north.';
