function renderCompareChoices(){for(const id of ['compareBefore','compareAfter']){const select=$(id);if(document.activeElement===select)continue;const value=select.value,options=[new Option('Choose a run…','')];for(const row of sessionChoices.values())options.push(new Option(privateView()?'Session '+String(options.length)+(row.active?' (active)':''):(row.label||row.id)+(row.active?' (active)':''),row.id));select.replaceChildren(...options);select.value=value;}}
function renderComparison(){renderCompareChoices();$('comparison').hidden=!compareData;if(!compareData)return;if(compareRendered===compareData&&comparePrivacy===privateView()&&$('compareRows').dataset.page===String(comparePage)+$('compareKind').value)return;compareRendered=compareData;comparePrivacy=privateView();const counts=$('compareCounts');counts.replaceChildren();for(const [key,label] of [['new','NEW ADDRESSES'],['returning','RETURNING'],['not_seen','NOT SEEN']]){const cell=element('div');cell.append(element('small',label),element('b',compareData.counts[key]));counts.append(cell);}$('compareCaveat').textContent=(compareData.partial?'Partial inventory: eviction or review limits may omit sightings. ':'')+compareData.note;const rows=compareData.groups[$('compareKind').value]||[];comparePage=Math.max(0,Math.min(comparePage,Math.ceil(rows.length/50)-1));const root=$('compareRows');root.replaceChildren();for(const d of rows.slice(comparePage*50,comparePage*50+50)){const box=element('div',undefined,'session-row');box.append(element('strong',name({...d,hits:d.hits||[]})),element('small',d.protocol.toUpperCase()+' · '+address(d)));root.append(box);}if(!rows.length)root.append(element('p','No addresses in this category.','helper'));root.dataset.page=String(comparePage)+$('compareKind').value;$('comparePage').textContent=rows.length?`${comparePage*50+1}–${Math.min(rows.length,(comparePage+1)*50)} of ${rows.length}`:'0 addresses';$('comparePrev').disabled=comparePage===0;$('compareNext').disabled=(comparePage+1)*50>=rows.length;}
$('compareSessions').onclick=async()=>{const before=$('compareBefore').value,after=$('compareAfter').value;if(!before||!after||before===after){$('compareStatus').textContent='Choose two different runs.';return;}$('compareSessions').disabled=true;$('compareStatus').textContent='Comparing inventories…';try{compareData=await api('/api/archive/compare?before='+encodeURIComponent(before)+'&after='+encodeURIComponent(after));comparePage=0;compareRendered=null;renderComparison();$('compareStatus').textContent='Comparison snapshot ready.';}catch(err){$('compareStatus').textContent=err.message;}finally{$('compareSessions').disabled=false;}};
for(const id of ['compareBefore','compareAfter'])$(id).onchange=()=>{compareData=null;renderComparison();$('compareStatus').textContent='Press Compare runs to refresh this selection.';};
$('compareKind').onchange=()=>{comparePage=0;compareRendered=null;renderComparison();};$('comparePrev').onclick=()=>{comparePage--;renderComparison();};$('compareNext').onclick=()=>{comparePage++;renderComparison();};
function cancelDeletion(){deleteTicket=null;$('deleteReview').hidden=true;$('deleteConfirmed').checked=false;$('confirmDeletion').disabled=true;}
function renderDeletion(){$('reviewDeletion').disabled=!selectedRuns.size;$('reviewDeletion').textContent='Review selected runs'+(selectedRuns.size?' ('+selectedRuns.size+')':'');if(!deleteTicket)return;$('deleteReview').hidden=false;$('deleteSummary').textContent=deleteTicket.count+' saved runs · '+megabytes(deleteTicket.bytes)+' · permanently removed, including logs, checkpoints and reports. Confirmation expires in 3 minutes.';const list=$('deleteNames');list.replaceChildren();for(const id of selectedRuns)list.append(element('p',privateView()?'Selected saved run':sessionChoices.get(id)?.label||id,'helper'));}
$('reviewDeletion').onclick=async()=>{const ids=Array.from(selectedRuns);$('reviewDeletion').disabled=true;try{const ticket=await api('/api/archive/delete/preview',{sessions:ids});if(JSON.stringify(ids)!==JSON.stringify(Array.from(selectedRuns)))return;cancelDeletion();deleteTicket=ticket;renderDeletion();}catch(err){notice(err.message);}finally{renderDeletion();}};
$('clearDeletion').onclick=()=>{selectedRuns.clear();cancelDeletion();renderSessionRows();};$('cancelDeletion').onclick=cancelDeletion;$('deleteConfirmed').onchange=()=>{$('confirmDeletion').disabled=!$('deleteConfirmed').checked;};
$('confirmDeletion').onclick=async()=>{if(!deleteTicket||!$('deleteConfirmed').checked)return;$('confirmDeletion').disabled=true;try{const result=await api('/api/archive/delete/confirm',{token:deleteTicket.token,confirmed:true});pending.add(result.id);cancelDeletion();notice('Deletion queued. Waiting for the Pager…');}catch(err){notice(err.message);cancelDeletion();}};

function renderKnownDevices(){const rows=state.known_devices||[],root=$('knownDevices');knownPage=Math.max(0,Math.min(knownPage,Math.ceil(rows.length/50)-1));root.replaceChildren();for(const note of rows.slice(knownPage*50,knownPage*50+50)){const d={key:note.key,address:note.key.split(':').slice(1).join(':'),protocol:note.key.split(':')[0],local_label:note.label,hits:[]};const box=element('div',undefined,'session-row'),info=element('div'),remove=element('button','Unmark known');info.append(element('strong',name(d)),element('small',d.protocol.toUpperCase()+' · '+address(d)));remove.disabled=privateView();remove.onclick=()=>control('device_note',{key:note.key,label:note.label||'',bookmark:!!note.bookmark,known:false});box.append(info,remove);root.append(box);}if(!rows.length)root.append(element('p','No known addresses saved. Open device details to mark your gear.','helper'));$('knownPage').textContent=rows.length?`${knownPage*50+1}–${Math.min(rows.length,(knownPage+1)*50)} of ${rows.length}`:'0 known addresses';$('knownPrev').disabled=knownPage===0;$('knownNext').disabled=(knownPage+1)*50>=rows.length;}
$('knownPrev').onclick=()=>{knownPage--;renderKnownDevices();};$('knownNext').onclick=()=>{knownPage++;renderKnownDevices();};

function stashResearchDraft(){if(researchInputKey&&researchDirty){researchDrafts.set(researchInputKey,{notes:$('researchNotes').value,links:$('researchLinks').value,revision:researchEditRevision});while(researchDrafts.size>20)researchDrafts.delete(researchDrafts.keys().next().value);}}
function researchLink(url,label){try{const u=new URL(url);if(!['http:','https:'].includes(u.protocol)||u.username||u.password)return null;const a=element('a',label||url);a.href=u.href;a.target='_blank';a.rel='noopener noreferrer';return a;}catch(_){return null;}}
async function loadResearch(offset=0){if(!selected||researchLoading)return;if(privateView()){notice('Turn Privacy off to load research details.');return;}stashResearchDraft();const key=selected,generation=++researchGeneration;researchLoading=true;$('openResearch').disabled=true;$('researchStatus').textContent='Reading local evidence and history…';try{const result=await api('/api/research/device?key='+encodeURIComponent(key)+'&offset='+offset);if(generation!==researchGeneration||selected!==key)return;if(researchData?.key!==key){researchPages.length=0;researchInputKey='';researchDirty=false;}if(!researchDirty)researchInputKey='';researchData=result;researchOffset=offset;$('researchPanel').hidden=false;$('researchStatus').textContent='Snapshot loaded. Research links open only when you tap them.';renderResearch(true);}catch(err){$('researchStatus').textContent=err.message;}finally{researchLoading=false;$('openResearch').disabled=false;}}
function renderResearch(force=false){
 const panel=$('researchPanel');if(!researchData||researchData.key!==selected){panel.hidden=true;return;}panel.hidden=false;const hidden=privateView();$('researchPrivate').hidden=!hidden;$('researchBody').hidden=hidden;$('evidenceDownload').href='/download/evidence.zip?key='+encodeURIComponent(researchData.key)+'&offset='+researchOffset;
 if(hidden){stashResearchDraft();$('researchNotes').value='';$('researchLinks').value='';researchInputKey='';$('researchPhotos').replaceChildren();$('researchIdentification').replaceChildren();$('researchReferences').replaceChildren();$('researchHistory').replaceChildren();panel.dataset.render='';return;}
 const signature=researchData.key+':'+researchData.notebook.revision+':'+researchOffset;if(!force&&panel.dataset.render===signature)return;panel.dataset.render=signature;
 const n=researchData.notebook,id=researchData.identification,ident=$('researchIdentification');ident.replaceChildren(element('strong',id.summary));for(const caution of id.cautions||[])ident.append(element('p',caution,'helper'));
 for(const hit of id.matches||[]){const box=element('details',undefined,'evidence');box.append(element('summary',hit.label+' · rule rank '+(hit.rank??'—')),element('p',hit.evidence));for(const t of hit.tests||[])box.append(element('p',`${t.matched?'Matched':'Not matched in this snapshot'}: ${t.field} ${t.op} ${t.expected} · observed ${t.observed}`,'helper'));ident.append(box);}
 const refs=$('researchReferences');refs.replaceChildren();for(const url of [...new Set([...(id.references||[]),...(n.links||[])])]){const a=researchLink(url);if(a)refs.append(a);}for(const shortcut of id.shortcuts||[]){const a=researchLink(shortcut.url,shortcut.label+' ↗');if(a)refs.append(a);}if(!refs.childElementCount)refs.append(element('p','No saved source links for this address.','helper'));
 if(researchInputKey!==researchData.key){const draft=researchDrafts.get(researchData.key);$('researchNotes').value=draft?draft.notes:n.notes;$('researchLinks').value=draft?draft.links:n.links.join('\n');researchEditRevision=draft?draft.revision:n.revision;researchDirty=!!draft;researchInputKey=researchData.key;}
 const storage=researchData.notebook_storage||{};$('researchStorage').textContent=storage.bytes==null?'Notebook storage information unavailable.':'Notebook: '+megabytes(storage.bytes)+' / '+megabytes(storage.limit_bytes)+' · '+megabytes(storage.free_bytes)+' free';const photos=$('researchPhotos');photos.replaceChildren();for(const photo of n.photos||[]){const box=element('figure'),img=element('img'),caption=element('figcaption',photo.name+' · user attachment'),remove=element('button','Remove attachment');img.alt=photo.name;img.loading='lazy';img.src='/download/research/photo?key='+encodeURIComponent(researchData.key)+'&id='+encodeURIComponent(photo.id);remove.disabled=researchDirty||researchSaving;remove.onclick=()=>removeResearchPhoto(photo.id);box.append(img,caption,remove);photos.append(box);}
 const h=researchData.history;$('researchHistoryScope').textContent=h.scanned_runs+' runs checked on this page · '+h.matches.length+' matching runs. '+(h.limited?'Partial read: some history may be omitted. ':'')+h.note;const history=$('researchHistory');history.replaceChildren();for(const row of h.matches){const box=element('div',undefined,'evidence');box.append(element('strong',row.session_label||row.session),element('p',(row.first_seen?new Date(row.first_seen*1000).toLocaleString():'Unknown first time')+' → '+(row.last_seen?new Date(row.last_seen*1000).toLocaleString():'Unknown last time')),element('p',(row.observations??'—')+' '+row.count_kind+(row.logged_tail?' + '+row.logged_tail+' logged tail records':'')+(row.partial?' · partial':'')));
 for(const [label,fix] of [['First receiver location',row.first_location],['Latest receiver location',row.last_location]])if(fix)box.append(element('p',label+': '+Number(fix.lat).toFixed(6)+', '+Number(fix.lon).toFixed(6)));history.append(box);}if(!h.matches.length)history.append(element('p','No exact-address sighting found on this page. Try older runs; limited logs may omit sightings.','helper'));$('researchOlder').disabled=h.next_offset==null||researchLoading;$('researchNewer').disabled=!researchPages.length||researchLoading;researchButtons();
}
function researchButtons(){for(const id of ['researchNotes','researchLinks','saveResearch','researchPhoto'])$(id).disabled=researchSaving||privateView();$('uploadResearchPhoto').disabled=researchSaving||researchDirty||privateView();for(const b of $('researchPhotos').querySelectorAll('button'))b.disabled=researchSaving||researchDirty;}
for(const id of ['researchNotes','researchLinks'])$(id).addEventListener('input',()=>{researchDirty=true;stashResearchDraft();researchButtons();$('researchStatus').textContent='Unsaved notes. Save before changing attachments.';});
$('openResearch').onclick=()=>loadResearch(0);$('reloadResearch').onclick=()=>loadResearch(researchOffset);$('discardResearchDraft').onclick=()=>{if(researchDirty&&!window.confirm('Discard these unsaved research notes?'))return;researchDrafts.delete(selected);researchInputKey='';researchDirty=false;loadResearch(researchOffset);};
$('researchOlder').onclick=()=>{if(researchLoading)return;const next=researchData?.history.next_offset;if(next!=null){researchPages.push(researchOffset);loadResearch(next);}};$('researchNewer').onclick=()=>{if(researchLoading)return;const offset=researchPages.pop();if(offset!==undefined)loadResearch(offset);};
async function saveResearchResult(operation){if(!researchData||privateView()||researchSaving)return;const key=researchData.key;researchSaving=true;researchButtons();try{const result=await operation(key);if(researchData?.key===key){researchData.notebook=result.notebook;if(result.storage)researchData.notebook_storage=result.storage;researchEditRevision=result.notebook.revision;researchDirty=false;researchDrafts.delete(key);researchInputKey='';renderResearch(true);}$('researchStatus').textContent='Research notebook saved.';}catch(err){$('researchStatus').textContent=err.message;}finally{researchSaving=false;researchButtons();}}
$('saveResearch').onclick=()=>saveResearchResult(key=>api('/api/research/note',{key,revision:researchEditRevision,notes:$('researchNotes').value,links:$('researchLinks').value.split(/\r?\n/).map(s=>s.trim()).filter(Boolean)}));
async function removeResearchPhoto(id){if(researchDirty){notice('Save your notes before removing attachments.');return;}if(!window.confirm('Remove this research attachment?'))return;await saveResearchResult(key=>api('/api/research/photo/remove',{key,id,revision:researchData.notebook.revision}));}
$('uploadResearchPhoto').onclick=async()=>{if(researchDirty||researchSaving||privateView())return;const file=$('researchPhoto').files?.[0];if(!file){notice('Choose a JPEG or PNG photo.');return;}if(!['image/jpeg','image/png'].includes(file.type)||file.size>20*1024*1024){notice('Choose a JPEG/PNG photo under 20 MB.');return;}const key=selected;try{const image=await createImageBitmap(file);const scale=Math.min(1,1600/image.width,1600/image.height),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);image.close();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.85));if(!blob||blob.size>2*1024*1024)throw Error('Photo is still too large. Choose a smaller image.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(blob);});if(selected!==key)return;await saveResearchResult(target=>api('/api/research/photo',{key:target,revision:researchData.notebook.revision,name:file.name.slice(0,80),data}));$('researchPhoto').value='';}catch(err){$('researchStatus').textContent='Photo not saved: '+err.message;}};
